import{_ as e,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"JDBC基本概念","description":"","frontmatter":{"title":"JDBC基本概念","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/01-JDBC/JDBC基本概念.md","filePath":"posts/java快速入门/第五部分：数据库/01-JDBC/JDBC基本概念.md"}'),n={name:"posts/java快速入门/第五部分：数据库/01-JDBC/JDBC基本概念.md"};function s(r,o,a,l,p,i){return c(),d("div",null,[...o[0]||(o[0]=[t('<div><p><strong>概念：</strong><code>Java DataBase Connectivity Java</code> 数据库连接， <code>Java</code>语言操作数据库 <code>* JDBC</code>本质：其实是官方（<code>sun</code>公司）定义的一套操作所有关系型数据库的规则，即接口。各个数据库厂商去实现这套接口，提供数据库驱动<code>jar</code>包。我们可以使用这套接口（<code>JDBC</code>）编程，真正执行的代码是驱动<code>jar</code>包中的实现类。</p><p><strong>快速入门：</strong><code>1.</code> 导入驱动<code>jar</code>包</p><ul><li>mysql-connector-java-5.1.37-bin.jar</li><li><ol><li></li></ol></li></ul><p>复制<code>mysql-connector-java-5.1.37-bin.jar</code>到项目的<code>libs</code>目录下 <code>2.</code>右键</p><ul><li>--&gt;Add As Library</li><li><ol start="2"><li></li></ol></li></ul><p>注册驱动，注：从 JDBC3 开始，目前已经普遍使用的版本。可以不用注册驱动而直接使用。Class.forName 这句话可以省略。 <code>3.</code> 获取数据库连接对象</p><ul><li>Connection</li><li>DriverManager</li></ul><p>类的作用：</p><p><code>1)</code></p><p>管理和注册驱动</p><p><code>2)</code></p><p>创建数据库的连接</p><p>连接数据库的 <code>URL</code> 地址格式： <strong>协议名</strong><code>:</code><strong>子协议</strong><code>://</code><strong>服务器名或</strong> <code>IP</code> <strong>地址</strong><code>:</code><strong>端口号</strong><code>/</code><strong>数据库名</strong><code>?</code><strong>参数</strong><code>=</code><strong>参数值</strong><code>MySQL</code> 中可以简写： <strong>前提：必须是本地服务器，端口号是</strong></p><p>3306 jdbc:mysql:/// <strong>数据库名</strong></p><p><strong>使用属性文件和</strong><code>url</code><strong>得到连接对象</strong></p><p><strong>乱码的处理</strong> 如果数据库出现乱码，可以指定参数<code>: ?characterEncoding=utf8</code>，表示让数据库以 <code>UTF-8</code> 编码来处理数据。 <code>jdbc:mysql://localhost:3306/</code>数据库<code>?characterEncoding=utf8</code></p><p><code>4.</code> 定义<code>sql</code></p><p><code>5.</code> 获取执行<code>sql</code>语句的对象</p><ul><li>Statement</li><li>Connection</li></ul><p>接口，具体的实现类由数据库的厂商实现，代表一个连接对象。</p><p><code>6.</code> 执行<code>sql</code>，接受返回结果 Statement 作用： 代表一条语句对象，用于发送 SQL 语句给服务器，用于执行静态 SQL 语句并返回它所生成结果的对象。</p><p><code>7.</code> 处理结果 <code>8.</code> 释放资源 <code>1)</code> 需要释放的对象：<code>ResultSet</code> 结果集，<code>Statement</code> 语句，<code>Connection</code> 连接</p><p><code>2)</code></p><p>释放原则：先开的后关，后开的先关。<code>ResultSet</code> -&gt; <code>Statement</code> -&gt;</p><ul><li>Connection</li><li><ol start="3"><li></li></ol></li></ul><p>放在哪个代码块中：<code>finally</code> 块</p><p><code>*</code> <strong>代码实现：新建表</strong></p><p><code>*</code> <strong>代码实现：插入数据</strong></p></div>',1)])])}const u=e(n,[["render",s]]);export{_ as __pageData,u as default};
